package com.spcomputers.service;
import com.razorpay.Order;
import com.razorpay.RazorpayClient;
import com.spcomputers.dto.CheckoutResponse;
import com.spcomputers.dto.PaymentVerifyRequest;
import com.spcomputers.entity.*;
import com.spcomputers.exception.ApiException;
import com.spcomputers.repository.*;
import org.json.JSONObject;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.math.RoundingMode;
@Service
public class CheckoutService {
 private final UserRepository users;private final CartRepository carts;private final OrderRepository orders;private final PaymentRepository payments;private final ProductRepository products;private final CartService cartService;private final ObjectProvider<RazorpayClient> razorpayProvider;private final String keyId;private final String keySecret;
 public CheckoutService(UserRepository users,CartRepository carts,OrderRepository orders,PaymentRepository payments,ProductRepository products,CartService cartService,ObjectProvider<RazorpayClient> razorpayProvider,@Value("${razorpay.key-id:}") String keyId,@Value("${razorpay.key-secret:}") String keySecret){this.users=users;this.carts=carts;this.orders=orders;this.payments=payments;this.products=products;this.cartService=cartService;this.razorpayProvider=razorpayProvider;this.keyId=keyId;this.keySecret=keySecret;}
 @Transactional public CheckoutResponse checkout(String email,String address){AppUser user=users.findByEmailIgnoreCase(email).orElseThrow(()->ApiException.notFound("User not found"));Cart cart=carts.findByUserId(user.getId()).orElseThrow(()->ApiException.badRequest("Your cart is empty"));if(cart.getItems().isEmpty())throw ApiException.badRequest("Your cart is empty");BigDecimal total=BigDecimal.ZERO;for(CartItem ci:cart.getItems()){Product p=ci.getProduct();if(!p.isActive())throw ApiException.conflict(p.getName()+" is no longer available");if(ci.getQuantity()>p.getStockQty())throw ApiException.conflict("Stock changed for "+p.getName());total=total.add(p.effectivePrice().multiply(BigDecimal.valueOf(ci.getQuantity())));}
  CustomerOrder order=new CustomerOrder();order.setUser(user);order.setTotalAmount(total.setScale(2,RoundingMode.HALF_UP));order.setOrderStatus(OrderStatus.PENDING);order.setShippingAddress(address.trim());for(CartItem ci:cart.getItems()){OrderItem oi=new OrderItem();oi.setProduct(ci.getProduct());oi.setProductName(ci.getProduct().getName());oi.setBrand(ci.getProduct().getBrand());oi.setUnitPrice(ci.getProduct().effectivePrice());oi.setQuantity(ci.getQuantity());order.addItem(oi);}orders.saveAndFlush(order);
  if(keyId.isBlank()||keySecret.isBlank())throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"Razorpay is not configured on the server");RazorpayClient client=razorpayProvider.getIfAvailable();if(client==null)throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"Razorpay is not configured on the server");long paise=order.getTotalAmount().multiply(BigDecimal.valueOf(100)).setScale(0,RoundingMode.HALF_UP).longValueExact();if(paise<100)throw ApiException.badRequest("Razorpay requires a payment of at least ₹1");try{JSONObject request=new JSONObject();request.put("amount",paise);request.put("currency","INR");request.put("receipt","spc_"+order.getId());JSONObject notes=new JSONObject();notes.put("sp_order_id",order.getId());request.put("notes",notes);JSONObject paymentOptions=new JSONObject();paymentOptions.put("capture","automatic");request.put("payment",paymentOptions);Order razorpayOrder=client.orders.create(request);Payment payment=new Payment();payment.setOrder(order);payment.setRazorpayOrderId(razorpayOrder.get("id"));payment.setStatus(PaymentStatus.CREATED);order.setPayment(payment);payments.save(payment);return new CheckoutResponse(order.getId(),payment.getRazorpayOrderId(),paise,"INR",keyId);}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"Unable to create Razorpay order");}
 }
 @Transactional public String verify(PaymentVerifyRequest request){Payment payment=payments.findByRazorpayOrderId(request.razorpay_order_id()).orElseThrow(()->ApiException.notFound("Payment order not found"));if(payment.getStatus()==PaymentStatus.CAPTURED){if(request.razorpay_payment_id().equals(payment.getRazorpayPaymentId()))return "Payment already verified";throw ApiException.conflict("Payment order has already been settled");}if(payment.getStatus()!=PaymentStatus.CREATED)throw ApiException.conflict("Payment is not awaiting verification");try{com.razorpay.Utils.verifySignature(request.razorpay_order_id()+"|"+request.razorpay_payment_id(),request.razorpay_signature(),keySecret);}catch(Exception e){throw new ApiException(HttpStatus.BAD_REQUEST,"Razorpay signature verification failed");}
  RazorpayClient gateway=razorpayProvider.getIfAvailable();if(gateway==null)throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"Razorpay is not configured on the server");try{com.razorpay.Payment gatewayPayment=gateway.payments.fetch(request.razorpay_payment_id());if(!request.razorpay_order_id().equals(gatewayPayment.get("order_id")))throw ApiException.conflict("Payment does not belong to this order");long expectedPaise=payment.getOrder().getTotalAmount().multiply(BigDecimal.valueOf(100)).setScale(0,RoundingMode.HALF_UP).longValueExact();long gatewayAmount=Long.parseLong(String.valueOf(gatewayPayment.get("amount")));if(gatewayAmount!=expectedPaise)throw ApiException.conflict("Payment amount does not match the order");String gatewayStatus=String.valueOf(gatewayPayment.get("status"));if("authorized".equalsIgnoreCase(gatewayStatus)){JSONObject captureRequest=new JSONObject();captureRequest.put("amount",expectedPaise);captureRequest.put("currency","INR");gatewayPayment=gateway.payments.capture(request.razorpay_payment_id(),captureRequest);gatewayStatus=String.valueOf(gatewayPayment.get("status"));}if(!"captured".equalsIgnoreCase(gatewayStatus))throw ApiException.conflict("Razorpay has not captured this payment yet");}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"Unable to confirm or capture the Razorpay payment");}
  CustomerOrder order=orders.findByIdForUpdate(payment.getOrder().getId()).orElseThrow(()->ApiException.notFound("Order not found"));if(order.getOrderStatus()==OrderStatus.CANCELLED)throw ApiException.conflict("This order has been cancelled");for(OrderItem item:order.getItems()){if(item.getProduct()==null)throw ApiException.conflict("An item in this order is no longer available");Product p=products.findByIdForUpdate(item.getProduct().getId()).orElseThrow(()->ApiException.notFound("Ordered product not found"));if(p.getStockQty()<item.getQuantity())throw ApiException.conflict("Insufficient stock for "+p.getName());p.setStockQty(p.getStockQty()-item.getQuantity());}
  payment.setRazorpayPaymentId(request.razorpay_payment_id());payment.setRazorpaySignature(request.razorpay_signature());payment.setStatus(PaymentStatus.CAPTURED);order.setOrderStatus(OrderStatus.PAID);cartService.clear(order.getUser().getId());return "Payment verified";
 }
}

